cmd:
_e=$(mktemp) || exit 2; [ -z "$(find . \( -name node_modules -o -name .git -o -name .venv -o -name __pycache__ -o -name .scan-workspaces \) -prune -o -name '*.sh' -not -path '*/canary/*' ! -type l -print -quit 2>>"$_e")" ] && {
  # fork19-CX12（Codex 终审#5）：空仓不删 _e——find 错误（如 EACCES）时仍走错误判定，
  # 原删 _e exit 0 = 错误吞没假 PASS（不可读目录内含 .sh 的仓误判干净）
  if [ -s "$_e" ]; then cat "$_e" >&2; rm -f "$_e"; exit 2; fi
  rm -f "$_e"; exit 0
}; _o=$(find . \( -name node_modules -o -name .git -o -name .venv -o -name __pycache__ -o -name .scan-workspaces \) -prune -o -name '*.sh' -not -path '*/canary/*' ! -type l -print0 2>>"$_e" | xargs -0 env LC_ALL=C awk '/^[[:space:]]*trap/ && /EXIT/ && !/^[[:space:]]*trap[[:space:]]+(-|--)+([[:space:]]+EXIT|[[:space:]]*$)/ {c[FILENAME]++} END {for (fn in c) if (c[fn]>1) print "double-EXIT-trap: " fn}' 2>>"$_e"); if [ -s "$_e" ]; then cat "$_e" >&2; rm -f "$_e"; exit 2; fi; rm -f "$_e"; [ -n "$_o" ] && { echo "$_o"; exit 1; }; exit 0
